// Build CBSE 11 Mathematics ch01 Sets. Run from platform/:
//   npx tsx content/authored/maths/cbse-11-mathematics-ch01/src/build.mjs
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { setUnit, topic, deck, sl, table, flow, build, chapterTests } from './lib.mjs';
import { range, S, arr, un, it, df, cp, subset, same, filt, tex, subsets, powerset, iv, inIv, agrees, ivTex, venn, venn2, venn3, vennNested, fromRegions, allSubsets } from './sets.mjs';
import { numberLine, NL_LOG } from './nl.mjs';

setUnit('cbse-11-mathematics-ch01');
await import('./questions.mjs');
await import('./questions2.mjs');
const DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');
const must = (cond, msg) => { if (!cond) throw new Error(`self-check failed: ${msg}`); };
const N = (a, b) => range(a, b);
const $ = (A) => `$${tex(A)}$`;
const prime = (x) => x > 1 && N(2, x - 1).every((p) => x % p);
const tick = (b) => (b ? '✓' : '✗');

// ================================================================ deck 1 visuals
const wd = table(['Collection', 'Well defined?', 'Why'], [['Prime numbers below $20$', '✓', $(filt(S(N(1, 19)), prime))], ['Tall students of the class', '✗', 'No clear rule for "tall"'], ['Vowels of the English alphabet', '✓', $(S(['a', 'e', 'i', 'o', 'u']))], ['Good songs of the year', '✗', 'Opinion, not a rule']], 'Table of four collections. Prime numbers below 20 and the vowels of the English alphabet are well defined sets with listed elements; tall students and good songs are not, because no clear rule decides membership.', 'A set needs a rule that settles membership.');
must(arr(filt(S(N(1, 19)), prime)).join() === '2,3,5,7,11,13,17,19', 'primes below 20');

const rbRows = [
  ['$\\{x \\in \\mathbb{N} : x \\text{ is a multiple of } 7,\\ x < 40\\}$', filt(S(N(1, 39)), (x) => x % 7 === 0)],
  ['$\\{x \\in \\mathbb{Z} : x^2 \\le 10\\}$', filt(S(N(-10, 10)), (x) => x * x <= 10)],
  ['$\\{x \\in \\mathbb{N} : x \\text{ divides } 18\\}$', filt(S(N(1, 60)), (x) => 18 % x === 0)],
  ['$\\{n^2 : n \\in \\mathbb{N},\\ n \\le 4\\}$', S(N(1, 4).map((n) => n * n))],
];
must(rbRows.map(([, A]) => arr(A).join()).join('|') === '7,14,21,28,35|-3,-2,-1,0,1,2,3|1,2,3,6,9,18|1,4,9,16', 'roster rows');
const rbTable = table(['Set-builder form', 'Roster form', 'Elements'], rbRows.map(([b, A]) => [b, $(A), `$${A.size}$`]), 'Table converting four sets from set-builder form to roster form: multiples of 7 below 40 give 7, 14, 21, 28, 35; integers with x squared at most 10 give minus 3 to 3; divisors of 18 give six numbers; squares of 1 to 4 give 1, 4, 9, 16.', 'Same set, two ways of writing it.');

const typeRows = [
  ['Empty', '$\\{x \\in \\mathbb{N} : x < 1\\}$', filt(S(N(1, 50)), (x) => x < 1)],
  ['Singleton', '$\\{x \\in \\mathbb{Z} : x + 4 = 4\\}$', filt(S(N(-30, 30)), (x) => x + 4 === 4)],
  ['Finite', '$\\{x \\in \\mathbb{N} : x \\text{ is a prime below } 12\\}$', filt(S(N(1, 11)), prime)],
];
must(typeRows.map(([, , A]) => A.size).join() === '0,1,5', 'type sizes');
const typesTable = table(['Type', 'Example', 'Number of elements'], [...typeRows.map(([t, e, A]) => [t, e, `$${A.size}$`]), ['Infinite', '$\\{x \\in \\mathbb{N} : x \\text{ is even}\\}$', 'never ends']], 'Table of types of sets with an example each: an empty set with 0 elements, a singleton with 1 element, a finite set of primes below 12 with 5 elements, and the infinite set of even natural numbers whose elements never end.', 'Count the elements to decide the type.');

const eqTable = table(['Description', 'Roster form (each element once)', 'Equal to $\\{1, 2, 3\\}$?'], [['$\\{3, 1, 2\\}$', $(S([3, 1, 2])), tick(same(S([3, 1, 2]), S([1, 2, 3])))], ['$\\{1, 2, 2, 3, 3\\}$', $(S([1, 2, 2, 3, 3])), tick(same(S([1, 2, 2, 3, 3]), S([1, 2, 3])))], ['$\\{x \\in \\mathbb{N} : x < 4\\}$', $(filt(S(N(1, 20)), (x) => x < 4)), tick(same(filt(S(N(1, 20)), (x) => x < 4), S([1, 2, 3])))], ['$\\{x \\in \\mathbb{N} : x \\le 4\\}$', $(filt(S(N(1, 20)), (x) => x <= 4)), tick(same(filt(S(N(1, 20)), (x) => x <= 4), S([1, 2, 3])))]], 'Table testing four sets against 1, 2, 3: the same elements in another order, with repeats, or described by x below 4 are all equal to it; the set described by x at most 4 has the extra element 4 and is not equal.', 'Order and repeats do not matter; the elements do.');
must(!same(filt(S(N(1, 20)), (x) => x <= 4), S([1, 2, 3])), 'x <= 4 differs');

const nested = vennNested(S(N(1, 6)), S([2, 4]), S(N(1, 8)), { mode: 'elems', alt: 'A Venn diagram inside a rectangle U of 1 to 8: a large circle A holds 1, 3, 5, 6 and, inside it, a small circle B holds 2 and 4; 7 and 8 lie outside both circles.', caption: '$B = \\{2, 4\\}$ sits inside $A = \\{1, 2, 3, 4, 5, 6\\}$: $B \\subset A$.' });
must(nested.regions['11'].join() === '2,4' && nested.regions['10'].join() === '1,3,5,6' && nested.regions['00'].join() === '7,8', 'nested regions');

const pA = S(['a', 'b', 'c']);
const pSets = subsets(pA);
const powerTable = table(['Size', 'Subsets of $\\{a, b, c\\}$', 'Count'], [0, 1, 2, 3].map((k) => { const L = pSets.filter((x) => x.length === k); return [`$${k}$`, L.map((x) => `$${x.length ? `\\{${x.join(', ')}\\}` : '\\varnothing'}$`).join(' '), `$${L.length}$`]; }), 'Table listing all 8 subsets of a, b, c by size: 1 subset of size 0, which is the empty set; 3 of size 1; 3 of size 2; and 1 of size 3, the set itself. The counts 1, 3, 3, 1 add up to 8.', 'Total $1 + 3 + 3 + 1 = 8 = 2^3$.');
must(pSets.length === 8 && pSets.map((x) => x.length).join('') === '01112223', 'power set sizes');
const powCount = table(['$n(A)$', '$0$', '$1$', '$2$', '$3$', '$4$', '$5$'], [['Subsets', ...N(0, 5).map((n) => `$${subsets(S(N(1, n))).length}$`)]], 'Table of the number of subsets of a set with 0, 1, 2, 3, 4 and 5 elements: 1, 2, 4, 8, 16, 32, doubling each time.', 'Each new element doubles the number of subsets: $2^n$.');
must(N(0, 5).map((n) => subsets(S(N(1, n))).length).join() === '1,2,4,8,16,32', 'doubling');

const univ = venn({ circles: [{ name: 'A', cx: 4.5, cy: 3, r: 2, set: S([2, 3, 5, 7]) }], U: S(N(1, 10)), mode: 'elems', alt: 'A rectangle U holding the numbers 1 to 10 with one circle A containing 2, 3, 5 and 7; the remaining numbers 1, 4, 6, 8, 9 and 10 lie outside the circle but inside the rectangle.', caption: 'The universal set $U = \\{1, 2, \\dots, 10\\}$ is the rectangle; $A$ is the circle of primes.' });
must(univ.regions['0'].join() === '1,4,6,8,9,10', 'outside A');

const IV = { a: iv(-2, 3, false, false), b: iv(-2, 3), c: iv(-2, 3, true, false), d: iv(-2, null, false) };
const pred = { a: (x) => -2 < x && x < 3, b: (x) => -2 <= x && x <= 3, c: (x) => -2 <= x && x < 3, d: (x) => x > -2 };
for (const k of 'abcd') must(agrees(pred[k], [IV[k]]), `interval ${k}`);
const nl1 = numberLine({ from: -4, to: 5, rows: [{ tag: '(-2, 3)', altTag: 'Row one, open interval', ivs: [IV.a] }, { tag: '[-2, 3]', altTag: 'Row two, closed interval', ivs: [IV.b] }, { tag: '[-2, 3)', altTag: 'Row three, half-open interval', ivs: [IV.c] }, { tag: '(-2, ∞)', altTag: 'Row four, unbounded interval', ivs: [IV.d] }] }, 'Open circles show excluded end points and filled circles show included ones; the arrow shows that the set goes on for ever.', { lead: 'Four interval types.' });
const ivTable = table(['Set-builder form', 'Interval', 'End points'], [['$\\{x \\in \\mathbb{R} : -2 < x < 3\\}$', `$${ivTex(IV.a)}$`, 'both excluded'], ['$\\{x \\in \\mathbb{R} : -2 \\le x \\le 3\\}$', `$${ivTex(IV.b)}$`, 'both included'], ['$\\{x \\in \\mathbb{R} : -2 \\le x < 3\\}$', `$${ivTex(IV.c)}$`, 'left in, right out'], ['$\\{x \\in \\mathbb{R} : x > -2\\}$', `$${ivTex(IV.d)}$`, 'infinity is never included']], 'Table pairing four set-builder descriptions with their interval notation: open interval from minus 2 to 3, closed interval, half-open interval with minus 2 included, and the unbounded interval above minus 2.', 'Round bracket: excluded. Square bracket: included.');
const chain = flow('LR', [['n', '$\\mathbb{N}$ natural'], ['w', '$\\mathbb{W}$ whole'], ['z', '$\\mathbb{Z}$ integers'], ['q', '$\\mathbb{Q}$ rationals'], ['r', '$\\mathbb{R}$ reals']], [['n', 'w', '$\\subset$'], ['w', 'z', '$\\subset$'], ['z', 'q', '$\\subset$'], ['q', 'r', '$\\subset$']], 'Flow diagram of number sets, each inside the next: natural numbers inside whole numbers inside integers inside rational numbers inside real numbers.', 'Each number set is a subset of the next.');
const ivInts = table(['Interval', 'Integers inside', 'Count'], ([[iv(-2, 3, false, false)], [iv(-2, 3)], [iv(-2, 3, true, false)]].map(([I]) => { const L = N(-6, 6).filter((x) => inIv(I, x)); return [`$${ivTex(I)}$`, `$${L.join(', ')}$`, `$${L.length}$`]; })), 'Table counting the integers in three intervals with end points minus 2 and 3: open gives minus 1 to 2, four integers; closed gives minus 2 to 3, six integers; left-closed right-open gives minus 2 to 2, five integers.', 'End points decide the count.');
must(ivInts.spec.rows.map((x) => x[2]).join() === '$4$,$6$,$5$', 'integer counts');
const summary1 = flow('LR', [['s', 'Set: well-defined collection'], ['f', 'Roster, set-builder, interval'], ['t', 'Empty, finite, infinite, equal'], ['p', 'Subsets and power set: $2^n$']], [['s', 'f'], ['f', 't'], ['t', 'p']], 'Summary flow: a set is a well-defined collection; write it in roster, set-builder or interval form; classify it as empty, finite, infinite or equal to another; subsets of an n-element set number 2 to the power n.', 'From a collection to its subsets.');

// ================================================================ deck 2 visuals
const U10 = S(N(1, 10)), P = S([2, 3, 5, 7]), O = S([1, 3, 5, 7, 9]);
const vBase = venn2(P, O, U10, { mode: 'elems', names: ['P', 'O'], alt: 'A Venn diagram of U equal to 1 to 10 with two overlapping circles: P holds the primes 2, 3, 5, 7 and O holds the odd numbers 1, 3, 5, 7, 9. Only P has 2; the overlap has 3, 5, 7; only O has 1 and 9; 4, 6, 8, 10 lie outside both.', caption: 'Primes $P$ and odd numbers $O$ in $U = \\{1, \\dots, 10\\}$.' });
must(vBase.regions['10'].join() === '2' && vBase.regions['11'].join() === '3,5,7' && vBase.regions['01'].join() === '1,9' && vBase.regions['00'].join() === '4,6,8,10', 'base regions');
const E3 = S([2, 4, 6]), O3 = S([1, 3, 5]);
const vDisj = venn({ circles: [{ name: 'E', cx: 2.9, cy: 3, r: 1.5, set: E3 }, { name: 'O', cx: 6.1, cy: 3, r: 1.5, set: O3 }], U: S(N(1, 8)), mode: 'elems', alt: 'A Venn diagram of U equal to 1 to 8 with two separate circles that do not touch: E holds 2, 4, 6 and O holds 1, 3, 5. The numbers 7 and 8 lie outside both. No number is in both circles.', caption: 'Disjoint sets: $E \\cap O = \\varnothing$.' });
must(it(E3, O3).size === 0 && vDisj.regions['11'].length === 0, 'disjoint');
const vComp = venn({ circles: [{ name: 'P', cx: 4.5, cy: 3, r: 2, set: P }], U: U10, mode: 'elems', alt: 'A rectangle U holding 1 to 10 with a circle P around the primes 2, 3, 5, 7. The complement of P is everything in the rectangle outside the circle: 1, 4, 6, 8, 9, 10.', caption: "The complement $P' = U - P$ is everything outside the circle." });
must(vComp.regions['0'].join() === arr(cp(U10, P)).join() && cp(U10, P).size === 6, 'complement');

const opRows = [['$P \\cup O$', un(P, O)], ['$P \\cap O$', it(P, O)], ['$P - O$', df(P, O)], ['$O - P$', df(O, P)], ["$P'$", cp(U10, P)], ["$(P \\cup O)'$", cp(U10, un(P, O))]];
must(opRows.map(([, A]) => arr(A).join()).join('|') === '1,2,3,5,7,9|3,5,7|2|1,9|1,4,6,8,9,10|4,6,8,10', 'op rows');
const opTable = table(['Operation', 'Result', 'Elements'], opRows.map(([n, A]) => [n, $(A), `$${A.size}$`]), 'Table of six operations on the prime set P and the odd set O inside U of 1 to 10: union has 6 elements, intersection has 3, P minus O has 1, O minus P has 2, the complement of P has 6, and the complement of the union has 4.', 'All six results, listed from the diagram.');

const lawNames = [
  ['Commutative', '$A \\cup B = B \\cup A$', (A, B) => same(un(A, B), un(B, A))],
  ['Commutative', '$A \\cap B = B \\cap A$', (A, B) => same(it(A, B), it(B, A))],
  ['Associative', '$(A \\cup B) \\cup C = A \\cup (B \\cup C)$', (A, B, C) => same(un(un(A, B), C), un(A, un(B, C)))],
  ['Distributive', '$A \\cap (B \\cup C) = (A \\cap B) \\cup (A \\cap C)$', (A, B, C) => same(it(A, un(B, C)), un(it(A, B), it(A, C)))],
  ['Distributive', '$A \\cup (B \\cap C) = (A \\cup B) \\cap (A \\cup C)$', (A, B, C) => same(un(A, it(B, C)), it(un(A, B), un(A, C)))],
  ['De Morgan', "$(A \\cup B)' = A' \\cap B'$", (A, B, C, Un) => same(cp(Un, un(A, B)), it(cp(Un, A), cp(Un, B)))],
  ['De Morgan', "$(A \\cap B)' = A' \\cup B'$", (A, B, C, Un) => same(cp(Un, it(A, B)), un(cp(Un, A), cp(Un, B)))],
  ['Identity', '$A \\cup \\varnothing = A$ and $A \\cap U = A$', (A, B, C, Un) => same(un(A, S([])), A) && same(it(A, Un), A)],
  ['Complement', "$A \\cup A' = U$ and $A \\cap A' = \\varnothing$", (A, B, C, Un) => same(un(A, cp(Un, A)), Un) && it(A, cp(Un, A)).size === 0],
];
const S4 = allSubsets(4), U4 = S(N(1, 4));
const lawOK = lawNames.map(([, , f]) => S4.every((A) => S4.every((B) => S4.every((C) => f(A, B, C, U4)))));
must(lawOK.every(Boolean), 'laws on all 4096 triples');
const lawTable = table(['Law', 'Statement', 'Checked on all $16^3$ triples of subsets of $\\{1, 2, 3, 4\\}$'], lawNames.map(([n, s], i) => [n, s, tick(lawOK[i])]), 'Table of nine laws of set algebra: commutative, associative, two distributive laws, two De Morgan laws, identity and complement, each with a tick showing it was checked on every triple of subsets of 1, 2, 3, 4.', 'Every law was verified by brute force.');
const regRows = [['Only $P$', true, false], ['In both', true, true], ['Only $O$', false, true], ['Neither', false, false]];
const regTable = table(['Region', 'In $P$', 'In $O$', "In $(P \\cup O)'$", "In $P' \\cap O'$"], regRows.map(([n, p, o]) => [n, tick(p), tick(o), tick(!(p || o)), tick(!p && !o)]), 'Table of the four regions of a two-circle Venn diagram. Only the region outside both circles lies in the complement of the union, and only that region lies in both P-complement and O-complement, so the two sets are equal.', 'The last two columns agree in every row: De Morgan.');
must(regRows.every(([, p, o]) => !(p || o) === (!p && !o)), 'region table');

const hobby = fromRegions({ a: 45, ab: 25, b: 30, none: 20 }); // A cycle app 70, B bus 55, both 25, total 120
must(hobby.U.size === 120 && hobby.A.size === 70 && hobby.B.size === 55 && it(hobby.A, hobby.B).size === 25 && un(hobby.A, hobby.B).size === 100, 'app counts');
const vCount2 = venn2(hobby.A, hobby.B, hobby.U, { mode: 'count', names: ['A', 'B'], alt: 'A Venn diagram of 120 members with two overlapping circles: A with 70 members and B with 55. Only A has 45, the overlap has 25, only B has 30, and 20 lie outside both circles.', caption: 'Counts: $45 + 25 + 30 + 20 = 120$.' });
must(vCount2.regions['10'].length === 45 && vCount2.regions['11'].length === 25 && vCount2.regions['01'].length === 30 && vCount2.regions['00'].length === 20, 'count regions');
const three = fromRegions({ abc: 3, ab: 5, bc: 4, ac: 6, a: 10, b: 9, c: 8, none: 5 });
const t3 = [three.A.size, three.B.size, three.C.size, it(three.A, three.B).size, it(three.B, three.C).size, it(three.A, three.C).size, it(it(three.A, three.B), three.C).size];
must(t3.join() === '24,21,21,8,7,9,3' && three.U.size === 50, `three-set data ${t3}`);
must(24 + 21 + 21 - 8 - 7 - 9 + 3 === un(un(three.A, three.B), three.C).size && un(un(three.A, three.B), three.C).size === 45, 'three-set formula');
const vCount3 = venn3(three.A, three.B, three.C, three.U, { mode: 'count', names: ['A', 'B', 'C'], alt: 'A Venn diagram of 50 learners with three overlapping circles A, B and C. The centre holds 3; the pairwise-only regions hold 5, 4 and 6; the single-set regions hold 10, 9 and 8; 5 lie outside all three circles.', caption: 'Region counts add to $50$; $n(A \\cup B \\cup C) = 45$.' });
must(Object.entries(vCount3.regions).sort().map(([k, v]) => `${k}:${v.length}`).join() === '000:5,001:8,010:9,011:4,100:10,101:6,110:5,111:3', Object.entries(vCount3.regions).sort().map(([k, v]) => `${k}:${v.length}`).join());

const A_i = iv(-3, 2, true, false), B_i = iv(0, 5, false, true);
const ia = (x) => inIv(A_i, x), ib = (x) => inIv(B_i, x);
const I_cap = iv(0, 2, false, false), I_cup = iv(-3, 5), I_diff = iv(-3, 0);
must(agrees((x) => ia(x) && ib(x), [I_cap]) && agrees((x) => ia(x) || ib(x), [I_cup]) && agrees((x) => ia(x) && !ib(x), [I_diff]), 'interval ops');
const nl2 = numberLine({ from: -4, to: 6, rows: [{ tag: 'A', ivs: [A_i] }, { tag: 'B', ivs: [B_i] }, { tag: 'A ∩ B', ivs: [I_cap] }, { tag: 'A ∪ B', ivs: [I_cup] }, { tag: 'A − B', ivs: [I_diff] }] }, 'Filled circles mark included end points and open circles mark excluded ones.', { lead: 'Operations on A equal to [-3, 2) and B equal to (0, 5].' });
const summary2 = flow('LR', [['u', 'Union, intersection, difference, complement'], ['l', 'Laws: commutative, associative, distributive, De Morgan'], ['c', '$n(A \\cup B) = n(A) + n(B) - n(A \\cap B)$'], ['t', 'Three sets: add singles, subtract pairs, add triple']], [['u', 'l'], ['l', 'c'], ['c', 't']], 'Summary flow: the four operations; the laws including De Morgan; the two-set counting formula; the three-set counting formula.', 'From operations to counting.');

// ================================================================ deck 1
const d1 = deck({
  part: 1, title: 'Sets — Part 1: Sets, subsets and intervals',
  goals: ['Decide when a collection is a set and write it in roster and set-builder form', 'Classify sets as empty, singleton, finite, infinite or equal', 'Find subsets and the power set of a finite set', 'Use the universal set and write intervals of real numbers'],
  slides: [
    sl('title', 'Sets, Part 1: Collections with a clear rule', { b: 'A set is a collection whose membership is settled by a clear rule.', v: wd, n: 'Welcome to Class Eleven mathematics. Everything in this course is built on sets. A set is a collection of objects with a clear rule that decides whether any object belongs. The prime numbers below twenty form a set. The tall students of a class do not, because tall has no exact meaning. In this part you will write sets in two ways, classify them, and count their subsets.' }),
    sl('concept', 'What you will be able to do', { ul: ['Tell a **well-defined** collection from an opinion', 'Write sets in **roster** and **set-builder** form', 'Classify **empty**, **finite**, **infinite** and **equal** sets', 'List **subsets** and count the **power set**', 'Write **intervals** on the real line'], n: 'Here are your goals for part one. You will learn to spot a genuine set, to write it by listing or by a rule, and to sort sets into types. Then you will study subsets, count them with a simple doubling rule, and finish with intervals, the sets of real numbers that every later chapter uses.' }),
    sl('concept', 'Elements and notation', { b: r`Objects in a set are its **elements**. We write $a \in A$ for "$a$ belongs to $A$" and $a \notin A$ otherwise. Capital letters name sets; standard sets are $\mathbb{N}$, $\mathbb{W}$, $\mathbb{Z}$, $\mathbb{Q}$, $\mathbb{R}$.`, v: chain, m: [r`\mathbb{N} \subset \mathbb{W} \subset \mathbb{Z} \subset \mathbb{Q} \subset \mathbb{R}`], n: 'The objects in a set are called its elements. We say that an element belongs to the set and use a rounded e symbol for it. Capital letters name sets. Five number sets have fixed names: natural numbers, whole numbers, integers, rational numbers and real numbers. Each is contained in the next, as the chain on screen shows.' }),
    sl('concept', 'Roster form and set-builder form', { b: r`**Roster form** lists the elements: $\{7, 14, 21\}$. **Set-builder form** gives a rule: $\{x \in \mathbb{N} : x \text{ is a multiple of } 7,\ x < 22\}$. Each element is listed once; order does not matter.`, v: rbTable, n: 'There are two ways to write a set. Roster form lists the elements between curly brackets. Set-builder form states a rule that every element satisfies, such as multiples of seven below forty. The table converts four sets from rule to list. Notice that the integers whose square is at most ten include negative numbers as well, so check the universe you are working in.' }),
    sl('check', 'Quick check: is it a set?', { b: 'Pick the collection that is well defined.', chk: 'm01', v: wd, n: 'Look for the option where a clear rule decides membership for every object.' }),
    sl('example', 'Worked example 1: from rule to list', { b: r`Write $A = \{x \in \mathbb{Z} : -3 \le 2x + 1 < 9\}$ in roster form and find $n(A)$.`, ul: ['Subtract $1$: $-4 \\le 2x < 8$', 'Divide by $2$: $-2 \\le x < 4$', 'Integers: $-2, -1, 0, 1, 2, 3$', '**Answer —** $A = \\{-2, -1, 0, 1, 2, 3\\}$, $n(A) = 6$'], v: table(['Step', 'Result'], [['Inequality', '$-3 \\le 2x + 1 < 9$'], ['Solve for $x$', '$-2 \\le x < 4$'], ['Integers in range', $(filt(S(N(-20, 20)), (x) => -3 <= 2 * x + 1 && 2 * x + 1 < 9))], ['Number of elements', '$6$']], 'Table of the steps for the worked example: the inequality, its solution minus 2 up to but not including 4, the six integers from minus 2 to 3, and the count 6.', 'Solve, then list the integers allowed.'), n: 'Solve the inequality like an equation. Subtract one from all three parts, then divide by two. The result says x is at least minus two and less than four. Now remember that x must be an integer, so list the integers in that range. There are six of them, so the set has six elements.' }),
    sl('concept', 'Types of sets', { b: r`**Empty** $\varnothing$: no element. **Singleton**: one element. **Finite**: counting ends. **Infinite**: it does not. Note $\{\varnothing\}$ is **not** empty; it has one element.`, v: typesTable, n: 'Sets are classified by their size. The empty set has no elements and is written with a slashed circle. A singleton has exactly one. A finite set can be counted to the end, while an infinite set, like the even natural numbers, never finishes. A trap to remember: a set containing the empty set has one element, so it is not itself empty.' }),
    sl('concept', 'Equal sets', { b: r`Sets $A$ and $B$ are **equal** when they have exactly the same elements. Repeating or reordering elements changes nothing. Equal sets have equal counts, but equal counts do **not** make sets equal.`, v: eqTable, n: 'Two sets are equal when they have exactly the same elements. Writing the elements in another order, or repeating one, does not change the set. The table tests four descriptions against the set one, two, three. The last one has an extra element four, so it is different. Remember also that two sets may have the same number of elements without being equal.' }),
    sl('check', 'Quick check: the empty set', { b: 'Is the set containing only the empty set itself an empty set?', chk: 'tf1', n: 'Count the elements inside the outer brackets.' }),
    sl('concept', 'Subsets', { b: r`$B \subseteq A$ if every element of $B$ is in $A$. If also $B \ne A$, then $B$ is a **proper subset**, written $B \subset A$. The empty set is a subset of every set, and every set is a subset of itself.`, v: nested.visual, n: 'A set B is a subset of A when every element of B also lies in A. In the picture, the small circle inside the large one shows this: two and four are in both. If B is not all of A, it is a proper subset. Two facts to memorise: the empty set is a subset of every set, and every set is a subset of itself.' }),
    sl('concept', 'The power set', { b: r`The set of all subsets of $A$ is the **power set** $P(A)$. If $n(A) = n$, then $P(A)$ has $2^n$ elements, because each element is either in or out of a subset.`, v: powerTable, n: 'List every subset of the three-element set a, b, c, sorted by size. There is one with no elements, three with one element, three with two, and one with all three. That is eight subsets in all. The reason is simple: each element is either in or out, two choices each, so three elements give two times two times two.' }),
    sl('diagram', 'Subsets double with each new element', { b: r`Subsets: $2^n$. Proper subsets: $2^n - 1$. Non-empty proper subsets: $2^n - 2$.`, v: powCount, n: 'Here is the doubling in numbers. A set with no elements has one subset, itself. Add one element and the count doubles to two, then four, eight, sixteen, thirty-two. Remove the set itself to count proper subsets, and remove the empty set as well to count the non-empty proper ones. These three counts are the usual one-mark questions.' }),
    sl('example', 'Worked example 2: counting with conditions', { b: r`How many subsets of $\{1, 2, 3, 4, 5\}$ contain both $3$ and $5$?`, ul: ['$3$ and $5$ must be in the subset', 'Each of $1, 2, 4$ is free: in or out', '**Answer —** $2^3 = 8$'], v: table(['Choice', 'Number of ways'], [['Fixed: $3$ and $5$ in', '$1$'], ['Free: $1$, $2$, $4$', '$2 \\times 2 \\times 2 = 8$'], ['Total subsets', `$${subsets(S(N(1, 5))).filter((a) => a.includes(3) && a.includes(5)).length}$`]], 'Table for the worked example: elements 3 and 5 are fixed inside, one way; elements 1, 2 and 4 are free, 2 times 2 times 2 ways; the total is 8 subsets.', 'Fixed elements add no choice.'), n: 'When some elements are forced into the subset, only the other elements give a choice. Here three and five must be inside, so there is only one way for them. The remaining elements one, two and four are each in or out, giving two cubed, which is eight subsets. Checking by listing all thirty-two subsets confirms the count.' }),
    sl('check', 'Quick check: subsets of a six-element set', { b: 'Fill in the number of subsets of a set with six elements.', chk: 'fb1', n: 'Use the doubling rule with six elements.' }),
    sl('concept', 'Universal set', { b: r`Within one discussion, all sets are subsets of a fixed **universal set** $U$, drawn as a rectangle. In a Venn diagram, circles inside the rectangle represent subsets.`, v: univ.visual, n: 'In any problem, all the sets live inside one larger set, called the universal set. We draw it as a rectangle, and draw each set as a circle inside. Here the universal set is the numbers one to ten and the circle holds the primes. The numbers left outside the circle but inside the rectangle are the ones that are not prime.' }),
    sl('concept', 'Intervals of real numbers', { b: r`Intervals are subsets of $\mathbb{R}$. A **square** bracket includes the end point; a **round** bracket excludes it. Infinity $\infty$ is never included.`, v: ivTable, n: 'Sets of real numbers between two end points are called intervals. A square bracket means the end point is included, a round bracket means it is excluded. The symbol for infinity always gets a round bracket, because it is not a number. The table matches four set-builder descriptions with their interval notation.' }),
    sl('diagram', 'Intervals on the number line', { b: r`Filled circle: included. Open circle: excluded. Arrow: continues for ever.`, v: nl1, n: 'On the number line, each interval is a thick line. A filled circle at an end point means the point is included, and an open circle means it is excluded. An arrow means the interval never stops. The four rows show an open interval, a closed interval, a half-open interval, and one that goes on for ever to the right.' }),
    sl('example', 'Worked example 3: integers in an interval', { b: r`How many integers lie in $(-2, 3)$, in $[-2, 3]$ and in $[-2, 3)$?`, ul: ['$(-2, 3)$: $-1, 0, 1, 2$ gives $4$', '$[-2, 3]$: $-2, \\dots, 3$ gives $6$', '$[-2, 3)$: $-2, \\dots, 2$ gives $5$'], v: ivInts, n: 'The end points decide the count. In the open interval both ends are removed, leaving minus one to two, four integers. In the closed interval both ends stay, giving minus two to three, six integers. The half-open interval keeps minus two but drops three, so it has five integers.' }),
    sl('check', 'Quick check: integers in an interval', { b: 'Count the integers in a half-open interval.', chk: 'm09', n: 'Decide first which end point is included and which is not.' }),
    sl('summary', 'Summary', { ul: ['Set: well-defined collection; roster form and set-builder form', 'Empty, singleton, finite, infinite; equal sets have the same elements', 'Subset, proper subset, universal set; $\\varnothing \\subseteq A$ always', 'Number of subsets of an $n$-element set: $2^n$', 'Intervals: square bracket included, round bracket excluded'], v: summary1, n: 'To sum up. A set is a well-defined collection, written by listing or by a rule. Sets can be empty, finite, infinite or equal. A subset has all its elements in the larger set, and a set with n elements has two to the power n subsets. Finally, intervals are sets of real numbers, with square brackets for included ends and round brackets for excluded ends.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Roster form (1–2 marks):** solve the condition, then list every element once', '**Subset counts (1–2 marks):** state $2^n$ and the reason', '**Intervals (1–2 marks):** correct brackets earn the mark; wrong end point loses it', '**Mistake:** calling $\\{\\varnothing\\}$ the empty set', '**Mistakes:** forgetting negative integers or $0$ in $\\mathbb{Z}$; a square bracket next to $\\infty$','**Not in this chapter:** Mathematical Induction is formative only'], n: 'In board-style answers, marks go to the roster form with every element listed once, to the power of two count with its reason, and to correct brackets in an interval. Common slips are calling a set that holds the empty set empty, forgetting negative integers, and putting a square bracket next to infinity. One note: proof by induction is only formative and is not examined here.' }),
  ],
});

// ================================================================ deck 2
const d2 = deck({
  part: 2, title: 'Sets — Part 2: Operations, laws and counting',
  goals: ['Find union, intersection, difference and complement from sets and Venn diagrams', 'Use the laws of set algebra including De Morgan', 'Operate on intervals', 'Solve word problems with the counting formulas for two and three sets'],
  slides: [
    sl('title', 'Sets, Part 2: Combining sets', { b: 'Union, intersection, difference and complement build new sets from old ones.', v: vBase.visual, n: 'Welcome to part two. Here two sets, the primes and the odd numbers up to ten, overlap in a Venn diagram. Three, five and seven are in both. You will see how to combine sets in four ways, how the laws of set algebra let you rewrite expressions, and how Venn diagrams turn word problems into simple counting.' }),
    sl('concept', 'What you will be able to do', { ul: ['Find $A \\cup B$, $A \\cap B$, $A - B$ and $A\'$', 'Read regions of a **Venn diagram**', 'Use **commutative**, **associative**, **distributive** and **De Morgan** laws', 'Operate on **intervals**', 'Count with $n(A \\cup B)$ and $n(A \\cup B \\cup C)$'], n: 'Here are your goals for part two. You will compute the four operations from lists and diagrams, apply the laws of set algebra, combine intervals on the number line, and solve practical counting problems with the union formula for two sets, and a lighter version for three.' }),
    sl('concept', 'Union and intersection', { b: r`$A \cup B$: elements in $A$ **or** $B$ (or both). $A \cap B$: elements in **both**. If $A \cap B = \varnothing$ the sets are **disjoint**.`, v: vBase.visual, m: [r`A \cup B = \{x : x \in A \text{ or } x \in B\}, \quad A \cap B = \{x : x \in A \text{ and } x \in B\}`], n: 'The union of two sets collects everything that is in the first, or the second, or both. The intersection keeps only what is in both. In the diagram, the union is all three regions inside the circles, and the intersection is the overlap with three, five and seven. Elements are listed once, even when they appear in both sets.' }),
    sl('diagram', 'Disjoint sets', { b: r`Sets with no common element are **disjoint**: their circles do not overlap and $E \cap O = \varnothing$.`, v: vDisj.visual, n: 'Sometimes two sets share nothing. The even numbers two, four, six and the odd numbers one, three, five are an example. Their circles do not touch, and their intersection is the empty set. Disjoint sets are important in counting, because the size of the union is then simply the sum of the two sizes.' }),
    sl('concept', 'Difference', { b: r`$A - B = \{x : x \in A \text{ and } x \notin B\}$. Note $A - B \ne B - A$ in general.`, v: vBase.visual, n: 'The difference of A and B keeps the elements of A that are not in B. With P for primes and O for odd numbers, P minus O is just the number two, the only even prime. O minus P is one and nine. The order matters: the two differences are different sets, one on each side of the overlap.' }),
    sl('concept', 'Complement', { b: r`$A' = U - A$: everything in $U$ that is **not** in $A$. Then $A \cup A' = U$ and $A \cap A' = \varnothing$.`, v: vComp.visual, n: 'The complement of a set is everything in the universal set that is outside it. It always depends on the universal set you chose. For the primes in the numbers one to ten, the complement is one, four, six, eight, nine and ten. A set and its complement together make the whole universal set and have nothing in common.' }),
    sl('check', 'Quick check: a complement', { b: 'How many tickets were not for the evening show?', chk: 'm14', n: 'The universal set is all the tickets sold. Subtract the evening tickets.' }),
    sl('example', 'Worked example 1: six operations', { b: r`For $U = \{1, \dots, 10\}$, $P$ = primes and $O$ = odd numbers, find $P \cup O$, $P \cap O$, $P - O$, $O - P$, $P'$ and $(P \cup O)'$.`, ul: ['Union: all elements of either set', 'Intersection: the overlap $\\{3, 5, 7\\}$', 'Differences: $P - O = \\{2\\}$, $O - P = \\{1, 9\\}$', 'Complements: from the numbers outside the circles'], v: opTable, n: 'Work from the diagram. The union lists one, two, three, five, seven and nine. The intersection is three, five, seven. The two differences are two on one side and one and nine on the other. The complement of the primes has six elements, and the complement of the union is four, six, eight and ten. Every result is read straight from a region.' }),
    sl('concept', 'Laws of set algebra', { b: 'Union and intersection are **commutative** and **associative**, and each **distributes** over the other. Identity and complement laws hold. The table was checked on every triple of subsets of a four-element set.', v: lawTable, n: 'Set operations obey laws much like those for numbers. Union and intersection can be swapped, regrouped, and each distributes over the other. There are also identity laws with the empty set and the universal set, and complement laws. The table lists nine laws, and each was verified by checking every possible triple of subsets of a four-element set.' }),
    sl('concept', 'De Morgan\'s laws', { b: r`$(A \cup B)' = A' \cap B'$ and $(A \cap B)' = A' \cup B'$. Complement flips union and intersection.`, v: regTable, n: 'De Morgan laws tell you how a complement passes through a union or an intersection. Not in A or B means not in A and not in B. The table checks the four regions of a two-circle diagram. Only the region outside both circles belongs to the complement of the union, and only that region belongs to both complements. So the two sets are the same.' }),
    sl('check', 'Quick check: De Morgan', { b: 'Pick the set equal to the complement of a union.', chk: 'm15', n: 'Recall that a complement flips the operation, so a union becomes an intersection of complements.' }),
    sl('example', 'Worked example 2: verify a law', { b: r`With $U = \{1, \dots, 9\}$, $A = \{2, 4, 6, 8\}$, $B = \{3, 6, 9\}$ verify $(A \cup B)' = A' \cap B'$.`, ul: ['$A \\cup B = \\{2, 3, 4, 6, 8, 9\\}$, so $(A \\cup B)\' = \\{1, 5, 7\\}$', '$A\' = \\{1, 3, 5, 7, 9\\}$, $B\' = \\{1, 2, 4, 5, 7, 8\\}$', '$A\' \\cap B\' = \\{1, 5, 7\\}$ — equal ✓'], v: table(['Expression', 'Set'], [['$A \\cup B$', $(un(S([2, 4, 6, 8]), S([3, 6, 9])))], ["$(A \\cup B)'$", $(cp(S(N(1, 9)), un(S([2, 4, 6, 8]), S([3, 6, 9]))))], ["$A' \\cap B'$", $(it(cp(S(N(1, 9)), S([2, 4, 6, 8])), cp(S(N(1, 9)), S([3, 6, 9]))))]], 'Table verifying one De Morgan law: the union of A and B is 2, 3, 4, 6, 8, 9; its complement is 1, 5, 7; and the intersection of the two complements is also 1, 5, 7.', 'Both sides give the same set.'), n: 'To verify a law with numbers, compute each side separately and compare. The union of A and B has six elements, and its complement in one to nine is one, five, seven. The complements of A and B each have more elements, but their intersection is again one, five, seven. The two sides agree, as the law predicts.' }),
    sl('diagram', 'Intervals: union, intersection, difference', { b: r`$A = [-3, 2)$, $B = (0, 5]$. Test each end point in **both** sets.`, v: nl2, n: 'Operations work on intervals too. Take minus three to two, excluding two, and zero to five, excluding zero. The intersection is zero to two, with both ends open, because zero is not in B and two is not in A. The union runs from minus three to five with both ends closed. The difference A minus B is minus three up to zero, including zero.' }),
    sl('example', 'Worked example 3: interval end points', { b: r`For the intervals above, find $A \cap B$, $A \cup B$ and $A - B$.`, ul: ['$A \\cap B = (0, 2)$: $0 \\notin B$, $2 \\notin A$', '$A \\cup B = [-3, 5]$: $-3 \\in A$, $5 \\in B$, no gap', '$A - B = [-3, 0]$: $0 \\in A$ and $0 \\notin B$'], v: table(['Set', 'Interval', 'Left end', 'Right end'], [['$A \\cap B$', `$${ivTex(I_cap)}$`, 'excluded', 'excluded'], ['$A \\cup B$', `$${ivTex(I_cup)}$`, 'included', 'included'], ['$A - B$', `$${ivTex(I_diff)}$`, 'included', 'included']], 'Table of the three interval results with their end points: the intersection from 0 to 2 has both ends excluded, the union from minus 3 to 5 has both ends included, and the difference from minus 3 to 0 has both ends included.', 'Decide each end point by testing it in both sets.'), n: 'The method is always the same. Find the end points, then test each one in both sets. Zero is not in B, so it cannot be in the intersection. Two is not in A, so the intersection excludes it too. For the union, minus three is in A and five is in B, so both stay. For the difference, zero is in A and not in B, so it stays.' }),
    sl('check', 'Quick check: intersect two intervals', { b: 'Find the intersection of two half-open intervals.', chk: 'm19', n: 'Test the end points in both intervals.' }),
    sl('concept', 'Counting two sets', { b: r`$n(A \cup B) = n(A) + n(B) - n(A \cap B)$. Also $n(A - B) = n(A) - n(A \cap B)$ and $n(A') = n(U) - n(A)$. **Formative only:** practical problems of this type are not board assessed.`, v: vCount2.visual, m: [r`n(A \cup B) = n(A) + n(B) - n(A \cap B)`], n: 'To count a union, add the two sizes and subtract the overlap, because the overlap was counted twice. In this example, among one hundred and twenty members, seventy use one app and fifty-five the other, with twenty-five using both. The diagram shows the four region counts, which add up to the total. These practical problems are for classroom practice and are not board assessed.' }),
    sl('example', 'Worked example 4: a word problem', { b: r`$120$ members: $70$ use app $A$, $55$ use app $B$, $25$ use both. How many use at least one, only $A$, neither?`, ul: ['At least one: $70 + 55 - 25 = 100$', 'Only $A$: $70 - 25 = 45$', 'Neither: $120 - 100 = 20$'], v: vCount2.visual, n: 'Start with the union formula: seventy plus fifty-five minus twenty-five gives one hundred members who use at least one app. Only the first app is seventy minus the overlap, forty-five. Those who use neither are the complement of the union: one hundred twenty minus one hundred, twenty. The diagram confirms all four regions.' }),
    sl('concept', 'Counting three sets', { b: r`$n(A \cup B \cup C) = n(A) + n(B) + n(C) - n(A \cap B) - n(B \cap C) - n(A \cap C) + n(A \cap B \cap C)$. Fill the Venn regions from the centre outwards.`, v: vCount3.visual, n: 'For three sets, add the three sizes, subtract the three pairwise overlaps, then add back the triple overlap, which was removed too often. In the diagram, start filling from the centre: the triple overlap, then the pairs, then the single regions. Here the three circles together hold forty-five of fifty learners, and five are outside all of them.' }),
    sl('check', 'Quick check: union count', { b: 'Count the students taking at least one of two subjects.', chk: 'm13', n: 'Add the two counts and remove the overlap once.' }),
    sl('summary', 'Summary', { ul: ['$A \\cup B$, $A \\cap B$, $A - B$, $A\'$ from regions of a Venn diagram', 'Laws: commutative, associative, distributive, identity, complement, De Morgan', 'Intervals: test every end point in both sets', '$n(A \\cup B) = n(A) + n(B) - n(A \\cap B)$', 'Three sets: singles, minus pairs, plus triple'], v: summary2, n: 'To sum up. The four operations come straight from Venn regions. The laws, especially De Morgan, let you rewrite expressions. On intervals, test each end point in both sets. For counting, add the sizes and subtract the overlap, and for three sets add back the triple overlap at the end.' }),
    sl('exam-tips', 'Exam tips: how marks are awarded', { ul: ['**Verify a law (2–3 marks):** compute both sides separately, then state they are equal', '**Proof of an identity (3–5 marks):** two inclusions with a general element $x$', '**Interval answers:** one mark per correct end-point decision', '**Mistake:** treating $A - B$ as $B - A$', '**Mistake:** subtracting the overlap twice, or not at all, in $n(A \\cup B)$', '**Mistake:** complement taken in the wrong universal set'], n: 'In board-style answers, verification questions give a mark for each side computed and one for the conclusion. Proofs of identities need both inclusions, written with a general element. Interval answers are marked end point by end point. Common slips are swapping the two differences, miscounting the overlap in the union formula, and taking a complement in the wrong universal set.' }),
  ],
});

// ================================================================ notes
const notes = {
  unit: 'cbse-11-mathematics-ch01', version: 1, title: 'Sets — chapter notes', language: 'en',
  sections: [
    { heading: '1. Sets and their representations', body_md: r`A **set** is a well-defined collection of objects; the objects are its **elements**. $a \in A$ means $a$ belongs to $A$.\n\n- **Roster form:** list the elements once each, e.g. $\{7, 14, 21, 28, 35\}$.\n- **Set-builder form:** give a rule, e.g. $\{x \in \mathbb{N} : x \text{ is a multiple of } 7,\ x < 40\}$.\n\nStandard sets: $\mathbb{N}$, $\mathbb{W}$, $\mathbb{Z}$, $\mathbb{Q}$, $\mathbb{R}$, each inside the next. For a set-builder rule, solve the condition inside the stated universe (negative integers count in $\mathbb{Z}$).`, key_terms: [{ term: 'Set', definition_md: 'A well-defined collection: a clear rule settles membership.' }, { term: 'Element', definition_md: r`An object in a set; $a \in A$.` }, { term: 'Roster form', definition_md: 'The set written by listing its elements.' }, { term: 'Set-builder form', definition_md: 'The set written by a rule its elements satisfy.' }], formulas: [{ latex: r`\{x \in \mathbb{N} : x < 5\} = \{1, 2, 3, 4\}`, label: 'Rule to roster' }], visual: rbTable, topic_ids: [topic(1)] },
    { heading: '2. Types of sets and equal sets', body_md: r`- **Empty set** $\varnothing$: no element. $\{\varnothing\}$ is **not** empty; it has one element.\n- **Singleton:** exactly one element.\n- **Finite:** counting ends; $n(A)$ is the number of elements.\n- **Infinite:** counting never ends.\n- **Equal sets:** exactly the same elements. Order and repeats do not matter. Equal counts do not make equal sets.\n\nTo show $A = B$, show $A \subseteq B$ and $B \subseteq A$.`, key_terms: [{ term: 'Empty set', definition_md: r`The set with no elements, $\varnothing$.` }, { term: 'Finite set', definition_md: 'A set whose elements can be counted to the end.' }, { term: 'Equal sets', definition_md: 'Sets with exactly the same elements.' }], formulas: [{ latex: r`A = B \iff A \subseteq B \text{ and } B \subseteq A`, label: 'Equality' }], visual: typesTable, visuals: [eqTable], topic_ids: [topic(1)] },
    { heading: '3. Subsets, power set and universal set', body_md: r`$B \subseteq A$ if every element of $B$ is in $A$; $B \subset A$ if also $B \ne A$ (**proper** subset). $\varnothing \subseteq A$ and $A \subseteq A$ always.\n\nThe **power set** $P(A)$ is the set of all subsets. If $n(A) = n$: subsets $2^n$; proper subsets $2^n - 1$; non-empty proper subsets $2^n - 2$. Fixing $k$ elements inside leaves $2^{n-k}$ subsets.\n\nThe **universal set** $U$ contains every set of the discussion; it is the rectangle of a Venn diagram.`, key_terms: [{ term: 'Subset', definition_md: r`$B \subseteq A$: every element of $B$ is in $A$.` }, { term: 'Power set', definition_md: r`$P(A)$: the set of all subsets of $A$.` }, { term: 'Universal set', definition_md: r`The set $U$ of which all sets under discussion are subsets.` }], formulas: [{ latex: r`n(P(A)) = 2^{n}`, label: 'Number of subsets' }], visual: powerTable, visuals: [nested.visual, powCount], topic_ids: [topic(2)] },
    { heading: '4. Intervals', body_md: r`Intervals are subsets of $\mathbb{R}$. $(a, b)$ excludes both ends; $[a, b]$ includes both; $[a, b)$ and $(a, b]$ include one. $(a, \infty)$ and $(-\infty, b]$ are unbounded. $\infty$ is never included.\n\nOn the number line: filled circle = included, open circle = excluded.\n\nIntegers in an interval: count the end points carefully. $(-2, 3)$ has $4$, $[-2, 3]$ has $6$, $[-2, 3)$ has $5$.`, key_terms: [{ term: 'Open interval', definition_md: r`$(a, b)$: both end points excluded.` }, { term: 'Closed interval', definition_md: r`$[a, b]$: both end points included.` }, { term: 'Half-open interval', definition_md: r`$[a, b)$ or $(a, b]$: one end included.` }], formulas: [{ latex: r`[a, b] = \{x \in \mathbb{R} : a \le x \le b\}`, label: 'Closed interval' }], visual: nl1, visuals: [ivTable, ivInts], topic_ids: [topic(2)] },
    { heading: '5. Venn diagrams and operations', body_md: r`- **Union** $A \cup B$: in $A$ or $B$ (or both).\n- **Intersection** $A \cap B$: in both. **Disjoint** if $A \cap B = \varnothing$.\n- **Difference** $A - B$: in $A$, not in $B$. In general $A - B \ne B - A$.\n- **Complement** $A' = U - A$.\n\nIn a Venn diagram, label the regions: only $A$, both, only $B$, outside. For intervals, test every end point in both sets: $[-3, 2) \cap (0, 5] = (0, 2)$, $[-3, 2) \cup (0, 5] = [-3, 5]$.`, key_terms: [{ term: 'Union', definition_md: 'All elements of either set, each listed once.' }, { term: 'Intersection', definition_md: 'The elements common to both sets.' }, { term: 'Complement', definition_md: r`$A' = U - A$, the elements of $U$ not in $A$.` }], formulas: [{ latex: r`A - B = A \cap B'`, label: 'Difference as intersection' }], visual: vBase.visual, visuals: [vDisj.visual, vComp.visual, opTable, nl2], topic_ids: [topic(3)] },
    { heading: '6. Laws of set algebra', body_md: r`- **Commutative:** $A \cup B = B \cup A$, $A \cap B = B \cap A$.\n- **Associative:** $(A \cup B) \cup C = A \cup (B \cup C)$, and the same for $\cap$.\n- **Distributive:** $A \cap (B \cup C) = (A \cap B) \cup (A \cap C)$, $A \cup (B \cap C) = (A \cup B) \cap (A \cup C)$.\n- **De Morgan:** $(A \cup B)' = A' \cap B'$, $(A \cap B)' = A' \cup B'$.\n- **Identity / complement:** $A \cup \varnothing = A$, $A \cap U = A$, $A \cup A' = U$, $A \cap A' = \varnothing$.\n\nTo **verify** a law, compute both sides for the given sets. To **prove** an identity, show each side is a subset of the other using a general element $x$.`, key_terms: [{ term: 'De Morgan\'s laws', definition_md: 'A complement turns a union into an intersection of complements and the reverse.' }, { term: 'Distributive law', definition_md: 'Each of union and intersection distributes over the other.' }], formulas: [{ latex: r`(A \cup B)' = A' \cap B', \qquad (A \cap B)' = A' \cup B'`, label: 'De Morgan' }], visual: lawTable, visuals: [regTable], topic_ids: [topic(3)] },
    { heading: '7. Counting with sets (formative practice)', body_md: r`Practical problems of this type are taught but not board assessed (formative assessment only).\n\n$n(A \cup B) = n(A) + n(B) - n(A \cap B)$, $n(A - B) = n(A) - n(A \cap B)$, $n(A') = n(U) - n(A)$. For disjoint sets, $n(A \cup B) = n(A) + n(B)$.\n\nThree sets: $n(A \cup B \cup C) = n(A) + n(B) + n(C) - n(A \cap B) - n(B \cap C) - n(A \cap C) + n(A \cap B \cap C)$.\n\nMethod: draw a Venn diagram and fill the **innermost region first**, then work outwards. Check that the regions add up to $n(U)$.`, key_terms: [{ term: 'n(A)', definition_md: 'The number of elements of the finite set $A$.' }], formulas: [{ latex: r`n(A \cup B) = n(A) + n(B) - n(A \cap B)`, label: 'Two sets' }], visual: vCount2.visual, visuals: [vCount3.visual], topic_ids: [topic(4)] },
  ],
  exam_tips_md: r`**How marks are awarded**\n- *Roster / set-builder (1–2 marks):* solve the condition, list each element once.\n- *Subset counts (1–2 marks):* $2^n$ with the reason.\n- *Verify a law (2–3 marks):* each side computed separately 1 + 1, conclusion 1.\n- *Prove an identity (3–5 marks):* each inclusion with a general $x$, then the conclusion.\n- *Intervals (2–5 marks):* one mark per correct end-point decision.\n- *Word problems (2–5 marks):* formula or Venn diagram 1, each region or total 1.\n\n**Common mistakes**\n1. Calling $\{\varnothing\}$ the empty set.\n2. Leaving out negative integers or $0$ when the universe is $\mathbb{Z}$.\n3. Treating $A - B$ as $B - A$.\n4. Writing a square bracket next to $\infty$.\n5. Counting the overlap twice in $n(A \cup B)$.\n6. Taking a complement in the wrong universal set.\n7. Proving a set identity with one example instead of a general element.\n8. Mathematical Induction is formative only and Mathematical Reasoning is deleted: neither is examined here.`,
  status: 'draft', provenance: d1.provenance,
};

